void test_c_dd_comp(Rng &rng, Report &report) {
  for (int iter = 0; iter < kIterations; ++iter) {
    Operand<dd_tag> a(random_qd(rng, Domain::any));
    Operand<dd_tag> b = near_operand<dd_tag>(ref_of(a), iter);
    int result = 2;
    c_dd_comp(a.limbs, b.limbs, &result);
    const qd_real diff = ref_of(a) - ref_of(b);
    const int expected = diff < 0.0 ? -1 : (diff > 0.0 ? 1 : 0);
    report.check("c_dd_comp", result == expected);
  }
}
