void test_c_qd_comp(Rng &rng, Report &report) {
  for (int iter = 0; iter < kIterations; ++iter) {
    Operand<qd_tag> a(random_qd(rng, Domain::any));
    Operand<qd_tag> b = near_operand<qd_tag>(ref_of(a), iter);
    int result = 2;
    c_qd_comp(a.limbs, b.limbs, &result);
    const qd_real diff = ref_of(a) - ref_of(b);
    const int expected = diff < 0.0 ? -1 : (diff > 0.0 ? 1 : 0);
    report.check("c_qd_comp", result == expected);
  }
}
