void test_c_edd_comp(Rng &rng, Report &report) {
  for (int iter = 0; iter < kIterations; ++iter) {
    Operand<edd_tag> a(random_qd(rng, Domain::any));
    Operand<edd_tag> b = near_operand<edd_tag>(ref_of(a), iter);
    int result = 2;
    c_edd_comp(a.limbs, b.limbs, &result);
    const qd_real diff = ref_of(a) - ref_of(b);
    const int expected = diff < 0.0 ? -1 : (diff > 0.0 ? 1 : 0);
    report.check("c_edd_comp", result == expected);
  }
}
